 s=(base/name).read_text(); heads=[]; offset=0; fence=False
 for line in s.splitlines(keepends=True):
  if line.startswith('"'```'"') or line.startswith('~~~'): fence=not fence
  m=re.match(r'"'^(#{1,6}) (.+?)'"\\n?"'$'"',line)
  if m and not fence: heads.append((offset,len(m.group(1)),re.sub(r'["'^'"\\w\\- ]','',m.group(2).lower()).replace(' ','-')))
  offset+=len(line)
 h=next(x for x in heads if x[2]==anchor); end=next((x[0] for x in heads if x[0]>h[0] and x[1]<=h[1]),len(s))
 return s[h[0]:end]
